// 1. Check for end of file or empty payload
if (!msg.payload || msg.payload === "" || (typeof msg.payload === 'object' && Object.keys(msg.payload).length === 0)) {
    // Send FINISHED to Output 2
    return [{ payload: "FINISHED" }, null];
}

const row = msg.payload;

// 2. Skip header row or invalid data
if (!row.HashApp || row.HashApp === "HashApp") {
    return null;
}

// 3. Sum daily invocations
let totalInvocations = 0;
for (let i = 1; i <= 1440; i++) {
    const value = parseInt(row[i], 10);
    if (!isNaN(value)) {
        totalInvocations += value;
    }
}

// 4. Filter and assign dynamic local path
if (totalInvocations > 15) {
    const validTriggers = ['http', 'queue', 'orchestration', 'timer', 'storage'];

    if (validTriggers.includes(row.Trigger)) {
        // Dynamically set local file path for the next node
        msg.filename = `/data/datasets/cleaned_${row.Trigger}_invocations.json`;

        msg.payload = {
            HashApp: row.HashApp,
            HashFunction: row.HashFunction,
            Trigger: row.Trigger,
            TotalDailyInvocations: totalInvocations
        };

        // Send data row to Output 1
        return [null, msg];
    }
}

return null;

// 1. Set the target S3 object name using the property we passed along
msg.filename = msg.minioFilename;

// 2. Add required metadata headers
msg.headers = {
    "X-Amz-Meta-Source": "AzureFunctionsDataset2019",
    "X-Amz-Meta-Status": "Unprocessed", 
    "X-Amz-Meta-ProcessedBy": "Node-RED-Pipeline"
};

return msg;

// 1. Define all the trigger types we processed
const triggers = ['http', 'queue', 'orchestration', 'timer', 'storage'];

// 2. Create a message for each file path
const fileMessages = triggers.map(type => {
    return {
        filename: `/data/datasets/cleaned_${type}_invocations.json`,
        minioFilename: `azure-cleaned-${type}-invocation.json`
    };
});

// 3. Output them sequentially to the next node
return [fileMessages];

const triggers = ['http', 'queue', 'orchestration', 'timer', 'storage'];

return triggers.map(t => {
    const script = `spark_kmeans_${t}.py`;
    return {
        payload: {
            action: "CreateSubmissionRequest",
            appResource: `/opt/spark/scripts/${script}`,
            clientSparkVersion: "4.1.2",
            mainClass: "org.apache.spark.deploy.PythonRunner",
            appArgs: [`/opt/spark/scripts/${script}`, ""],
            environmentVariables: {},
            sparkProperties: {
                "spark.master": "spark://spark-master:7077",
                "spark.submit.deployMode": "cluster",
                "spark.cores.max": "2",
                "spark.app.name": `KMeans_${t}`,
                "spark.driver.extraJavaOptions": "-Divy.cache.dir=/tmp/ivy -Divy.home=/tmp/ivy",
                "spark.jars": "/opt/spark/external_jars/hadoop-aws-3.3.4.jar,/opt/spark/external_jars/aws-java-sdk-bundle-1.12.262.jar"
            }
        }
    };
});

// 1. List all 5 files that need a reset
const triggers = ['http', 'queue', 'orchestration', 'timer', 'storage'];

const deleteMessages = triggers.map(type => {
    return {
        filename: `/data/datasets/cleaned_${type}_invocations.json`
    };
});

// 2. Output 5 individual messages to the delete node
return [deleteMessages];

// Load AWS SDK (registered in settings.js functionGlobalContext)
const AWS = global.get('AWS');

// Define accepted trigger types and output labels
const validTriggers = ['http', 'queue', 'orchestration', 'timer', 'storage'];
const labels = ['low', 'mid', 'high'];

// Extract input from the POST body
const trigger = msg.payload.trigger;
const total = msg.payload.totalDailyInvocations;
const res = msg.res;

// --- Validation ---
// Reject if trigger is not one of the 5 known types, or total is not a positive integer
if (!validTriggers.includes(trigger) || !Number.isInteger(total) || total <= 0) {
    return { payload: "invalid input", statusCode: 400, res: res };
}

node.warn("Total Daily Invocations are: " + total);

// --- MinIO client setup ---
// Configure S3-compatible client pointing to the MinIO container
const s3 = new AWS.S3({
    endpoint: 'http://minio-iis:9000',
    accessKeyId: 'minioadmin',
    secretAccessKey: 'minioadmin',
    s3ForcePathStyle: true,
    signatureVersion: 'v4'
});

const bucket = 'azure-functions-raw';
const prefix = `results/${trigger}/centroids.csv/`;

// --- Step 1: List centroids directory to find the actual part file ---
// Spark writes files like: centroids.csv/part-00000-<uuid>-c000.csv
return s3.listObjects({ Bucket: bucket, Prefix: prefix }).promise()
    .then(data => {
        // Find the first part file (ignore _SUCCESS or other metadata files)
        const objects = data.Contents || [];
        const partFile = objects.find(o => o.Key.includes('part-'));
        if (!partFile) throw new Error('No centroids file found');

        // --- Step 2: Download the CSV content ---
        return s3.getObject({ Bucket: bucket, Key: partFile.Key }).promise();
    })
    .then(data => {
        // --- Step 3: Parse the CSV into centroid rows ---
        // Expected format:
        //   cluster_id,centroid_invocations
        //   0,376.4
        //   1,1984364.0
        //   2,11482.0
        const csv = data.Body.toString('utf8');
        const lines = csv.trim().split('\n').filter(l => l.length > 0);

        // Skip the header row, parse each data row
        const centroids = [];
        for (let i = 1; i < lines.length; i++) {
            const parts = lines[i].split(',');
            // const clusterId = parseInt(parts[0]);
            const centroidValue = parseFloat(parts[1]);
            centroids.push(centroidValue);
        }

        // Order centroids by centroidValue ascending.
        // centroids = centroids.sort((a, b) => a.centroidValue - b.centroidValue);
        centroids.sort((a, b) => a - b);

        node.warn("sorted centroids are " + centroids);

        // --- Step 4: Find the cluster with centroid closest to the input total ---
        let nearestCluster = centroids[0];
        let smallestDifference = Math.abs(centroids[0] - total);

        for (let i = 1; i < centroids.length; i++) {
            const currentDiff = Math.abs(centroids[i] - total);
            if (currentDiff < smallestDifference) {
                smallestDifference = currentDiff;
                nearestCluster = centroids[i];
            }
        }

        // --- Step 5: Map cluster ID to a label and return it ---
        // Cluster 0 -> "low", 1 -> "mid", 2 -> "high"
        const resultLabel = labels[centroids.indexOf(nearestCluster)] || 'unknown';

        node.warn("Result label: " + resultLabel);
        return { payload: resultLabel, res: res };
    })
    .catch(err => {
        // Any error (MinIO unavailable, file missing, etc.) returns 400
        return { payload: "Bad luck", statusCode: 500, res: res };
    });

// 1. Ανακτούμε το Kubernetes Object που είχαμε σώσει στο Βήμα 2
let deployment = msg.kube_object;

// 2. Διαβάζουμε το tier που μόλις επέστρεψε ο κόμβος http request
// (Προσαρμόζεις το msg.payload ανάλογα με το τι επιστρέφει το δικό σου Validate & Classify)
let tier = msg.payload || "low";

node.warn("Function tier is: " + tier);

// 3. Δημιουργία των απαραίτητων sub-objects για να μην κρασάρει η JS
if (!deployment.spec) deployment.spec = {};
if (!deployment.spec.template) deployment.spec.template = {};
if (!deployment.spec.template.metadata) deployment.spec.template.metadata = {};
if (!deployment.spec.template.metadata.labels) deployment.spec.template.metadata.labels = {};
if (!deployment.spec.template.spec) deployment.spec.template.spec = {};

// 4. Εισαγωγή του Workload Label
deployment.spec.template.metadata.labels["azure-workload"] = tier;

// 5. Τα 2 σταθερά καλούπια Affinity / Anti-Affinity
const ANTI_AFFINITY_HIGH = {
    podAntiAffinity: {
        preferredDuringSchedulingIgnoredDuringExecution: [{
            weight: 100,
            podAffinityTerm: {
                labelSelector: {
                    matchExpressions: [{ key: "azure-workload", operator: "In", values: ["high"] }]
                },
                topologyKey: "kubernetes.io/hostname"
            }
        }]
    }
};

const AFFINITY_LOW_MID = {
    podAffinity: {
        preferredDuringSchedulingIgnoredDuringExecution: [{
            weight: 50,
            podAffinityTerm: {
                labelSelector: {
                    matchExpressions: [{ key: "azure-workload", operator: "In", values: ["low", "mid"] }]
                },
                topologyKey: "kubernetes.io/hostname"
            }
        }]
    }
};

// 6. Απόφαση βάσει του API
if (tier === "high") {
    deployment.spec.template.spec.affinity = ANTI_AFFINITY_HIGH;
} else {
    deployment.spec.template.spec.affinity = AFFINITY_LOW_MID;
}

// 7. Επαναφέρουμε το τελικό τροποποιημένο αντικείμενο στο payload για να γίνει YAML
msg.payload = deployment;
return msg;

// 1. Παίρνουμε το έτοιμο αντικείμενο από το payload και το σώζουμε στο kube_object
// για να μην το σβήσει το HTTP Request που ακολουθεί
msg.kube_object = msg.payload;

// 2. Έλεγχος ασφαλείας: Υπάρχουν τα annotations στο YAML;
if (msg.kube_object && msg.kube_object.metadata && msg.kube_object.metadata.annotations) {
    let annotations = msg.kube_object.metadata.annotations;

    // 3. Προετοιμάζουμε το payload για το Classification API
    msg.payload = {
        trigger: annotations.trigger,
        totalDailyInvocations: parseInt(annotations.totalDailyInvocations)
    };

    return msg;
} else {
    // Αν το YAML δεν έχει annotations, βγάλε ειδοποίηση στο debug και σταμάτα τη ροή
    node.error("Το YAML δεν περιέχει metadata.annotations!", msg);
    return null; 
}
